const SYSTEM = `You analyse customer reviews for a car rental company in Germany.
Reviews can be German or English. Return ONLY a JSON object with these keys:
- language: "de" | "en" | "other"
- sentiment: "positive" | "neutral" | "negative"
- category: one of "pickup_wait", "car_condition", "staff", "pricing_fees", "booking_app", "damage_claim", "safety", "other"
- urgency: "low" | "medium" | "high"  (high = safety issue, legal threat, or angry repeat customer)
- summary_en: one short English sentence
- reply_draft: a polite reply in the SAME language as the review, max 70 words, no promises of refunds`;

return $input.all().map((item, i) => {
  const b = item.json.body ?? item.json;
  const text = String(b.text ?? b.review ?? '').trim().slice(0, 4000);
  const rating = Number(b.rating);
  return {
    json: {
      review_id: b.review_id ?? `rev_${Date.now()}_${i}`,
      source: b.source ?? 'unknown',
      author: b.author ?? 'anonymous',
      branch: b.branch ?? 'unknown',
      rating: Number.isFinite(rating) ? Math.min(5, Math.max(1, rating)) : null,
      text,
      valid: text.length >= 3,
      received_at: new Date().toISOString(),
      openai_body: {
        model: 'gpt-4o-mini',
        temperature: 0.2,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: SYSTEM },
          { role: 'user', content: `Rating: ${Number.isFinite(rating) ? rating : 'n/a'}/5\nBranch: ${b.branch ?? 'unknown'}\nReview: ${text}` }
        ]
      }
    }
  };
});

const base = $('Normalize & Validate').all();
const ALLOWED = {
  sentiment: ['positive', 'neutral', 'negative'],
  urgency: ['low', 'medium', 'high'],
  category: ['pickup_wait', 'car_condition', 'staff', 'pricing_fees', 'booking_app', 'damage_claim', 'safety', 'other'],
};

return $input.all().map((item, i) => {
  const r = base[i].json;
  let ai = null, ai_error = '';
  try {
    ai = JSON.parse(item.json.choices[0].message.content);
    for (const [k, vals] of Object.entries(ALLOWED)) {
      if (!vals.includes(ai[k])) throw new Error(`invalid ${k}: ${ai[k]}`);
    }
  } catch (e) {
    ai_error = item.json.error ? 'OpenAI request failed' : `Parse error: ${e.message}`;
    ai = null;
  }
  // Fallback: never lose a review just because the AI step failed
  const fallbackSentiment = r.rating == null ? 'neutral' : r.rating <= 2 ? 'negative' : r.rating >= 4 ? 'positive' : 'neutral';
  const out = {
    review_id: r.review_id,
    received_at: r.received_at,
    source: r.source,
    branch: r.branch,
    author: r.author,
    rating: r.rating,
    text: r.text,
    language: ai?.language ?? 'unknown',
    sentiment: ai?.sentiment ?? fallbackSentiment,
    category: ai?.category ?? 'other',
    urgency: ai?.urgency ?? (r.rating != null && r.rating <= 2 ? 'medium' : 'low'),
    summary_en: ai?.summary_en ?? '',
    reply_draft: ai?.reply_draft ?? '',
    ai_status: ai ? 'ok' : 'fallback',
    ai_error,
  };
  out.needs_escalation =
    out.urgency === 'high' ||
    out.category === 'safety' ||
    (out.sentiment === 'negative' && (out.rating ?? 5) <= 2) ||
    out.ai_status === 'fallback';
  return { json: out };
});

