const weekAgo = Date.now() - 7 * 24 * 3600 * 1000;
const rows = $input.all().map(i => i.json).filter(r => Date.parse(r.received_at) >= weekAgo);

const count = (key) => rows.reduce((acc, r) => { acc[r[key]] = (acc[r[key]] || 0) + 1; return acc; }, {});
const rated = rows.filter(r => Number(r.rating) > 0);
const avg = rated.length ? (rated.reduce((s, r) => s + Number(r.rating), 0) / rated.length).toFixed(2) : 'n/a';
const negatives = rows.filter(r => r.sentiment === 'negative');
const byBranch = {};
for (const r of rows) {
  byBranch[r.branch] ??= { total: 0, negative: 0 };
  byBranch[r.branch].total++;
  if (r.sentiment === 'negative') byBranch[r.branch].negative++;
}

const stats = {
  period_start: new Date(weekAgo).toISOString().slice(0, 10),
  period_end: new Date().toISOString().slice(0, 10),
  total: rows.length,
  avg_rating: avg,
  sentiment: count('sentiment'),
  categories: count('category'),
  by_branch: byBranch,
  escalated: rows.filter(r => String(r.needs_escalation) === 'true').length,
  negative_examples: negatives.slice(0, 8).map(r => `[${r.branch}, ${r.category}] ${r.summary_en || r.text.slice(0, 160)}`),
};

return [{
  json: {
    stats,
    openai_body: {
      model: 'gpt-4o-mini',
      temperature: 0.3,
      messages: [
        { role: 'system', content: 'You write a short weekly customer-feedback briefing for a product manager at a car rental company. Use plain English, max 150 words: 1) headline trend, 2) top 2 problems with numbers, 3) one concrete product or process suggestion. No fluff.' },
        { role: 'user', content: JSON.stringify(stats) }
      ]
    }
  }
}];

const s = $('Build Weekly Stats').first().json.stats;
const summary = $input.first().json.choices?.[0]?.message?.content ?? '(AI summary unavailable this week)';
const esc = (t) => String(t).replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const table = (obj) => Object.entries(obj).sort((a, b) => b[1] - a[1])
  .map(([k, v]) => `<tr><td style="padding:4px 12px 4px 0">${esc(k)}</td><td><b>${v}</b></td></tr>`).join('');
const branches = Object.entries(s.by_branch)
  .map(([b, v]) => `<tr><td style="padding:4px 12px 4px 0">${esc(b)}</td><td>${v.total} reviews, ${v.negative} negative</td></tr>`).join('');

const html = `
<div style="font-family:Arial,sans-serif;max-width:620px">
  <h2 style="margin-bottom:4px">Weekly Review Briefing</h2>
  <p style="color:#666;margin-top:0">${s.period_start} to ${s.period_end} · ${s.total} reviews · avg rating ${s.avg_rating} · ${s.escalated} escalated</p>
  <div style="background:#f3f6ff;padding:12px 16px;border-radius:8px;white-space:pre-wrap">${esc(summary)}</div>
  <h3>Sentiment</h3><table>${table(s.sentiment)}</table>
  <h3>Top categories</h3><table>${table(s.categories)}</table>
  <h3>By branch</h3><table>${branches}</table>
  <p style="color:#999;font-size:12px">Generated automatically by n8n.</p>
</div>`;
return [{ json: { subject: `Review briefing ${s.period_end}: ${s.total} reviews, avg ${s.avg_rating}`, html } }];
